//! Moonlander physical geometry, generated by `scripts/extract-geometry.mjs`
//! from QMK's `keyboard.json` into `shared/moonlander_geometry.json`.
//! Foundation-owned; regenerate the JSON rather than editing it.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::error::AppError;

pub const GEOMETRY_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../shared/moonlander_geometry.json"
));

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct GeometryFile {
    /// e.g. "zsa/moonlander/reva"
    pub keyboard: String,
    pub layout_macro: String,
    pub key_count: u32,
    /// In LAYOUT-arg order — same order as `Layer::keys`.
    pub keys: Vec<GeometryKey>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct GeometryKey {
    pub x: f64,
    pub y: f64,
    pub w: f64,
    pub h: f64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub r: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rx: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ry: Option<f64>,
    /// [row, col] in the switch matrix.
    pub matrix: [u8; 2],
    /// Index into `rgb_matrix.layout[]` / the ledmap.
    pub led: u8,
}

pub fn get() -> Result<GeometryFile, AppError> {
    let geo: GeometryFile = serde_json::from_str(GEOMETRY_JSON)
        .map_err(|e| AppError::InvalidLayout(format!("geometry: {e}")))?;
    if geo.keys.len() != geo.key_count as usize {
        return Err(AppError::InvalidLayout(format!(
            "geometry keyCount {} != keys.len() {}",
            geo.key_count,
            geo.keys.len()
        )));
    }
    Ok(geo)
}

/// Geometry for a registry keyboard. Geometry JSONs are compiled in; adding
/// a board to `shared/keyboards.json` means embedding its file here too.
pub fn get_for_keyboard(keyboard_id: &str) -> Result<GeometryFile, AppError> {
    let kb = crate::keyboards::get(keyboard_id)?;
    match kb.geometry_file.as_str() {
        "moonlander_geometry.json" => get(),
        other => Err(AppError::InvalidLayout(format!(
            "no geometry embedded for {other:?} (keyboard {:?})",
            kb.id
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::layout::MOONLANDER_KEY_COUNT;

    #[test]
    fn geometry_parses_with_72_keys_and_unique_leds() {
        let geo = get().unwrap();
        assert_eq!(geo.keys.len(), MOONLANDER_KEY_COUNT);
        assert_eq!(geo.layout_macro, "LAYOUT_moonlander");
        let mut leds: Vec<u8> = geo.keys.iter().map(|k| k.led).collect();
        leds.sort_unstable();
        leds.dedup();
        assert_eq!(leds.len(), MOONLANDER_KEY_COUNT, "LED indices must be unique");
    }
}
